#anchor 右手首 trail
#particles 3600
#blend additive
#bloom
#lights 2

// Hand Sparks — both hands throwing sparks.
//
// Bound to BOTH WRISTS, so the source travels with her: sparks leave each hand
// wherever she puts it, and a fast hand throws them further than a still one.
// That is the difference between an effect that is IN a performance and one that
// is behind it — change the anchors at the top of this file and they throw from
// wherever you name instead.
//
// NO RIBBON. The trail mount would draw a solid band between the samples of a
// hand's path, and a band is a different object: it reads as cloth or as light
// wrapped around her. These are only ever separate sparks, thrown and falling,
// so what draws her movement is the shape of the shower rather than a line.
//
// A TEMPERATURE RUN, NOT A PALETTE. Flame goes blue, then white, then yellow,
// then red as it cools, so the hottest thing in the picture is the blue one —
// the instant a spark leaves her hand. Reading the colours in that order is what
// makes the shower look like something burning rather than something tinted, and
// it is where the colour comes from without any of it being invented.
//
// The blue segment is deliberately SHORT. The blue core of a real flame is
// always its smallest part; stretch it and the whole thing reads as a gas jet.
//
// It pours continuously rather than in bursts. The engine staggers the pool's
// lifetimes anyway, so the fan is dense at every instant instead of pulsing.
//
// THE STREAK IS THE SPEED, which is the one idea worth taking from the spark
// shaders that draw these as cylinders. A spark's length on screen is its
// velocity: it leaves at fifteen metres a second as a long thin line, the air
// takes that away in a fraction of a second, and by the time it falls it is a
// dot. Drawing every spark the same length is what makes a shower look like
// confetti. The engine stretches a quad along its own velocity in the CAMERA's
// basis, so the length is recomputed from the live speed each frame and reads
// correctly from any angle.
//
// The sparks are BALLISTIC. Thrown outward, slowed hard by drag, pulled down by
// gravity, and dying young — which is what separates a spark from a firefly.

// Tunables.
const SPEED = 4.6;         // metres a second, leaving the bone
const SPEED_VAR = 0.85;    // how much that varies spark to spark — a few go far
const CONE = 0.75;         // half-angle of the spray, radians. 0.75 is about 43 degrees
const INHERIT = 0.5;       // how much of the hand's own motion they carry away
const GRAVITY = 4.2;
const DRAG = 2.4;          // per second. Air stops a spark fast, and that is the look
const LIFE = 1.0;          // they carry past the hand that threw them
const LIFE_VAR = 0.7;
// HAIRLINE. The width is the whole difference between a needle and a dash: at
// 0.012 a spark is about a pixel across at stage distance, and the stretch below
// turns that pixel into a scratch. Widen it and the fan becomes a spray of rice.
const SIZE = 0.024;
const LENGTH = 1.9;        // streak length per metre/second of speed
const LENGTH_MAX = 16.0;   // and its ceiling, so a fast one is a line and not a smear
const BLUE = vec3f(0.42, 0.68, 1.00); // the instant it leaves her — hottest
const HOT = vec3f(1.00, 0.97, 0.86);  // white
const WARM = vec3f(1.00, 0.46, 0.07); // burning down
const DEAD = vec3f(0.44, 0.04, 0.01); // and out
const BLUE_END = 0.12;    // how much of a spark's life is still blue — keep it short
const WHITE_END = 0.34;
const GAIN = 4.6;          // HDR: white here is grey after AgX
const LIGHT_COLOR = vec3f(1.00, 0.62, 0.22);  // the shower's body, not its blue tip
const LIGHT_I = 1.15;
const LIGHT_R = 7.0;      // world units — an arm's length, not the room
const LIGHT_REST = 0.4;   // what a still hand keeps
const LIGHT_FULL = 9.0;   // hand speed at which the light is fully up

/**
 * The temperature run: 0 the instant a spark is thrown, 1 as it goes out.
 * Blue, white, orange, red — in that order, because that is the order metal
 * cools in.
 */
fn burnColor(t: f32) -> vec3f {
  if (t < BLUE_END) {
    return mix(BLUE, HOT, clamp(t / BLUE_END, 0.0, 1.0));
  }
  if (t < WHITE_END) {
    return mix(HOT, WARM, clamp((t - BLUE_END) / (WHITE_END - BLUE_END), 0.0, 1.0));
  }
  return mix(WARM, DEAD, clamp((t - WHITE_END) / (1.0 - WHITE_END), 0.0, 1.0));
}

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  let r = rzHash13(seed + f32(id) * 0.0211);
  let r2 = rzHash13(seed * 2.17 + f32(id) * 0.0473);

  // EITHER HAND. The slot is chosen per spark, so both wrists throw from the
  // same pool and neither has to be given half of it up front — a hand held
  // still simply stops drawing from it.
  let slot = select(0, 1, r.z > 0.5);
  let a = rzAnchor(0, slot);
  // No such bone on this rig: park it dead rather than showering the world
  // origin, which is what an unchecked anchor does on every model that spells
  // the name differently.
  if (!a.valid) {
    p.life = 0.0;
    p.pos = vec3f(0.0, -1000.0, 0.0);
    return p;
  }
  p.pos = a.pos;

  // A NARROW CONE ALONG THE BONE, not a sphere. A torch throws its spray one
  // way — the way the tool is pointing — and a full-sphere emitter is a
  // dandelion. rzAnchor gives the bone's own forward axis, so the spray turns
  // with her wrist for free.
  //
  // Uniform in cos(theta) rather than in theta: sampling the angle directly
  // crowds the axis and leaves the rim of the cone thin.
  var axis = a.fwd;
  if (dot(axis, axis) < 1e-6) { axis = vec3f(0.0, 1.0, 0.0); }
  axis = normalize(axis);
  // A frame around it. Crossing with +Y collapses when the bone points up, so
  // the second axis is chosen away from it. (Not named "ref" — WGSL reserves it,
  // and the error lands on the line that USES the variable rather than the one
  // that declares it.)
  let away = select(vec3f(0.0, 1.0, 0.0), vec3f(1.0, 0.0, 0.0), abs(axis.y) > 0.9);
  let t = normalize(cross(away, axis));
  let b = cross(axis, t);
  let phi = r.x * 6.2831853;
  let cz = mix(1.0, cos(CONE), r.y);
  let sz = sqrt(max(0.0, 1.0 - cz * cz));
  let dir = normalize(axis * cz + (t * cos(phi) + b * sin(phi)) * sz);

  // Fast, and varying hard: a shower where every spark leaves at the same rate
  // has a visible front edge to it.
  let speed = SPEED * mix(1.0 - SPEED_VAR, 1.0 + SPEED_VAR, r2.x * r2.x);
  // And it carries some of the hand away with it, so a thrown arm throws sparks.
  p.vel = dir * speed + a.vel * INHERIT;

  p.size = SIZE * mix(0.6, 1.4, r2.y);
  // Set here and recomputed every step: the length IS the speed.
  p.stretch = clamp(speed * LENGTH, 1.0, LENGTH_MAX);
  p.life = LIFE * (1.0 - LIFE_VAR * 0.5 + LIFE_VAR * r2.z);
  p.seed = seed + f32(id) * 0.0211;
  return p;
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  var q = p;
  // Drag first, then gravity: a spark is light, so the air takes its speed away
  // long before the ground takes its height. Exponential, so the result does not
  // depend on the frame rate.
  q.vel = q.vel * exp(-DRAG * dt);
  q.vel.y = q.vel.y - GRAVITY * dt;
  q.pos = q.pos + q.vel * dt;
  // The streak follows the speed down. A spark that keeps its launch length
  // after the air has stopped it is a dash hanging in the air.
  q.stretch = clamp(length(q.vel) * LENGTH, 1.0, LENGTH_MAX);
  return q;
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  let q = (uv - vec2f(0.5)) * 2.0;
  let r = length(q);
  // Compact support: exactly zero at the quad's edge, so bloom has no square to
  // find. A hard core inside a soft one — the shape of something incandescent.
  let core = pow(1.0 - clamp(r, 0.0, 1.0), 3.0);
  let hot = core * core;

  let age = clamp(p.age / max(p.life, 1e-4), 0.0, 1.0);
  let col = burnColor(age);
  // It dims as it cools, and it dies out rather than being cut off.
  let fade = pow(1.0 - age, 1.6);
  let e = clamp(hot + core * 0.35, 0.0, 1.0) * fade;
  if (e <= 0.0) { return vec4f(0.0); }
  return vec4f(col * GAIN, e);
}

/**
 * One lamp at the fuse, so the spit actually lights her hand.
 *
 * Bloom spreads bright pixels in screen space and never enters shading — a
 * bloomed spark does not illuminate the sleeve next to it. This does.
 */
fn lightEmit(i: u32, time: f32) -> RzLight {
  var l: RzLight;
  // The shower's BODY, never the blue tip. A blue-white lamp on skin reads as
  // moonlight, and the colour a viewer takes off the sparks is the orange they
  // spend most of their life at.
  l.color = LIGHT_COLOR;
  l.intensity = 0.0;
  l.radius = 1.0;
  l.pos = vec3f(0.0, 0.0, 0.0);

  // One lamp per wrist. Slot 0 is the left and 1 the right, the order the
  // anchors are declared at the top — the light index IS the slot here, unlike
  // the sparks, which pick a hand each.
  //
  // SUBJECT 0 only. A light is a declared cost, and covering four dancers would
  // spend eight of the sixteen slots on one effect.
  let a = rzAnchor(0, i32(i));
  if (!a.valid) { return l; }
  l.pos = a.pos;
  l.radius = LIGHT_R;

  // HOW FAST SHE IS MOVING, AVERAGED OVER THE WHOLE RECORDED PATH.
  //
  // Not length(a.vel): that is one frame's velocity, and a pose track is sampled
  // rather than smooth, so it jumps between frames. A light driven by it
  // flickers on the model and no curve fixes that, because the input is the
  // noise. Walking the path and dividing the distance covered by how long it
  // took is an average over the trail's whole span, so the light can change only
  // as fast as a hand can change its mind.
  //
  // Path LENGTH, not the distance between the ends — a circling hand returns to
  // where it started and would otherwise read as standing still. Divine Ribbon
  // arrived at the same thing for the same reason.
  let n = rzTrailCount(0, i32(i));
  var travelled = 0.0;
  if (n >= 2) {
    var prev = rzTrail(0, i32(i), 0).xyz;
    for (var s = 1; s < n; s = s + 1) {
      let cur = rzTrail(0, i32(i), s).xyz;
      travelled = travelled + distance(prev, cur);
      prev = cur;
    }
  }
  let span = max(rzTrail(0, i32(i), max(n - 1, 0)).w, 1e-3);
  l.intensity = LIGHT_I * mix(LIGHT_REST, 1.0, clamp((travelled / span) / LIGHT_FULL, 0.0, 1.0));
  return l;
}

#grid 512

// WHERE SHE MEETS THE WATER, which is not always a foot. Six joints down each
// limb, so whichever ones are actually crossing the surface are the ones that
// ring: ankles when she walks, knees when she kneels, wrists when she trails a
// hand. The torso comes free through rzSubjectHip and costs no slot.
//
// Six of the scene's sixteen anchor slots. That table is shared by every
// installed effect, so an effect wanting hands as well should expect to be told
// the budget is spent — see EFFECT_ANCHORS.
#anchor 左足首
#anchor 右足首
#anchor 左ひざ
#anchor 右ひざ
#anchor 左手首
#anchor 右手首

// Water — a surface with a depth, that something can stand in.
//
// The motion is the grid mount: a wave equation after Evan Wallace's WebGL
// Water, whose update is three lines and is stated PER FRAME:
//
//   info.g += (average - info.r) * 2.0;   // acceleration toward the neighbours
//   info.g *= 0.995;                      // damping
//   info.r += info.g;                     // integrate
//
// This is the half that could not be a texture. A ripple has to LEAVE the foot
// that made it, spread, and reflect off the far edge seconds later — that is
// memory, and the grid is the only thing in this engine that has any. Every
// procedural surface pattern tried here was a function of position and could
// only ever look like one.
//
// A Blender anime-water graph was surveyed for the LOOK (tools/blender-port,
// 194 nodes flattened to 82) and three things in it are worth recording even
// though its layers are not in this file:
//
//   1. ANISOTROPY. Every mapping node scales one axis and not the other —
//      (0.11, 1, 1), (2.55, 1, 1), (4.22, 1, 1). Stretching the domain nine
//      times along one axis is what turns noise into FLOW.
//   2. VORONOI, not fbm, for foam cells: round and separated, which is what
//      foam is. fbm gives connected veins, which is marble.
//   3. Ramps 0.032 to 0.064 wide on a 0..1 field. That hard cut is the cel edge.
//
// They were ported and REMOVED. Their thresholds were measured on a field
// sampled in a normalised 0..1 domain and then read back in WORLD units through
// invented conversion factors, so they landed nowhere near the coverage they
// were placed at, every layer saturated, and the surface came out a carpet of
// white confetti. Doing it properly means sampling in the domain the thresholds
// were measured in, which is its own piece of work rather than a tuning pass.

// ── The pool ─────────────────────────────────────────────────────────────────
// WATER_Y is the surface height in world units, and it is the dial that decides
// what this scene IS. A model stands about 20 units tall, so:
//   0.5   a wet floor — ankles break the surface as she dances
//   4.0   shallow water, a ring off every step
//   10.0  waist deep, wading
//   16.0  swimming
// Anything below the surface is simply covered by it: the depth test does that
// for free, so her legs go under with no per-model work.
const WATER_Y: f32 = 4.0;
const SIM_AT: vec2f = vec2f(0.0, 0.0);
// How wide the pool is. Independent of how FAST its waves look, which is the
// non-obvious part and worth stating: a ripple's crossing time is
//
//     N / (sqrt(WAVE_SPEED/2) * fps)
//
// — the GRID, not the span. Widening the pool makes each texel cover more
// world, so the wave covers more world per frame too, and the two cancel
// exactly. Raising the grid to 1024 for sharpness therefore doubled how long a
// ripple took to cross (19 seconds), and a 19-second ripple does not read as
// water, it reads as the surface slowly warping. 512 puts it at 8.8s and costs
// a quarter as much: the step runs one invocation per texel per frame.
//
// So widening this is nearly free in the ways that matter — the pace is
// unchanged and the surface detail is procedural, so neither cares. What it
// does cost is SIMULATION resolution: 340 units over 512 texels is 660mm each,
// and a footfall ring is about fifteen of them. Past roughly 400 the rings
// start to show their steps, and the answer then is a bigger grid and a slower
// wave, which is a trade rather than a fix.
const SIM_SPAN: f32 = 340.0;

// ── The wave equation ────────────────────────────────────────────────────────
// Backed off the stability limit deliberately. It also sets how fast a ring
// GROWS, and a slower ring stays near whoever made it — which matters more here
// than crossing the pool quickly, now that ripples are spent before they could.
const WAVE_SPEED: f32 = 1.4;
// PER FRAME, and the only thing that decides how FAR a ripple carries — width
// does not enter into it. At 39 units a second the half-distances are: 0.991 to
// 50 units, 0.982 to 25, 0.968 to 14. The pool's radius is 170, so anything
// above about 0.98 sends rings most of the way across it and they arrive
// looking as strong as they left, which is what reads as wrong — a real ripple
// is spent within a few paces.
const DAMPING: f32 = 0.955;
// HEIGHT damping, and its absence was a real bug rather than a small number.
// Wallace damps the VELOCITY only, which is right for an endless pool: a
// displaced height then loses amplitude solely by radiating, so a ring keeps
// almost everything it started with and simply travels. Measured, that ring was
// still visible 101 units out after two seconds and arrived looking as strong
// as it left. Damping the height as well makes a ripple actually SPEND itself:
// with these two it is gone inside about a second, which is what a footfall in
// a pool does.
const HEIGHT_DAMPING: f32 = 0.965;
// The only thing that sets a ripple's WIDTH — damping does not touch it, so
// these two are independent. Measured: 5.0 gives a 10.6-unit ring, 3.5 gives
// 8.0, and 2.5 gives 6.6 but at 10 texels it is nearing the point where the
// ring shows its steps rather than its shape.
const STEP_R: f32 = 3.5;          // world units a limb disturbs
const LIMB_SLOTS: i32 = 6;        // how many of the anchors above to read
const STEP_PUSH: f32 = 0.30;      // depth of the dent it presses
const STEP_BAND: f32 = 3.0;       // how near the surface it has to be
const STEP_SPEED: f32 = 0.35;     // extra push per unit of speed

// ── Colour ───────────────────────────────────────────────────────────────────
// Blue, not teal. The green was coming from the body colour itself, not from
// the light — a pool reads as blue because water absorbs red first and leaves
// the short end of the spectrum, so the deep end should get BLUER as it darkens
// rather than greyer.
// CRYSTAL, which is a claim about the DEEP end more than the shallow one. Dirty
// water darkens toward black as it deepens because the light is scattered out
// of it; clear water stays BLUE, because the only thing removing light is
// absorption and absorption spares the short wavelengths. So the deep colour
// keeps its blue and simply loses the rest — that, plus a lower absorption
// coefficient below, is the whole difference between a pool and a pond.
// DEEP is the colour of open water with NOTHING under it, and that is the case
// it has to carry: with no floor the depth term saturates immediately, so this
// single colour is the whole pool. It was mixed as an absence — the shallow
// tone with the light taken out — which is why it went slate. Water with no
// bottom is not darker water, it is BLUER water: the red is gone by then and
// what is left is the short end, still bright.
const DEEP: vec3f = vec3f(0.030, 0.330, 0.780);
const SHALLOW: vec3f = vec3f(0.210, 0.660, 0.950);
const FOAM: vec3f = vec3f(0.95, 1.0, 1.0);
const SKY_LOW: vec3f = vec3f(0.72, 0.86, 0.95);
const SKY_HIGH: vec3f = vec3f(0.30, 0.58, 0.95);
const MIRRORING: f32 = 0.30;      // sky surviving a straight-down view
// CLEAR looking down through a hand's depth, murky through a body's. This is
// the pair that makes someone look like they are IN the water rather than
// behind a coloured sheet: her shins show through, her thighs go green, and the
// waterline is where the two meet.
// A FLOOR IS NOT AN ABSENCE OF WATER. At 0.14 a shallow pool was so nearly
// invisible that whatever lay under it — a ground plane, its grid — simply
// showed through unchanged, and the surface stopped reading as a surface at all
// wherever it was shallow. Worse, it made a hard edge exactly where the floor
// ended and the depth term jumped: water on one side, floor on the other.
//
// 0.34 still shows the bottom clearly, which is what clear water does. It just
// no longer pretends to be nothing.
const CLEAR: f32 = 0.34;          // a shallow column tints, without hiding
const OPACITY: f32 = 0.88;        // a deep one hides what is under it
// Shorter, so the shallows reach the deep colour sooner and the boundary where
// a floor ends stops announcing itself.
const COLUMN: f32 = 14.0;         // world units of water to go from one to the other
const WADE_FOAM: f32 = 2.5;       // world units of foam collar at the waterline
// ── Seen from inside ─────────────────────────────────────────────────────────
// A plane has no inside, and that is exactly what gives a fake one away: put
// the camera below it and the world is unchanged. Water is a VOLUME, so a ray
// that starts underwater is tinted by however far it travels before it leaves.
//
// Beer-Lambert rather than a linear ramp: absorption is exponential, which is
// why a metre of pool water is nearly clear and ten metres is opaque. A linear
// fade cannot be both, and reads as a coloured sheet at every distance.
const UNDER_TINT: vec3f = vec3f(0.070, 0.470, 0.780);
const UNDER_RANGE: f32 = 30.0;    // world units to lose most of the colour
const UNDER_MAX: f32 = 0.88;      // never quite opaque, so the scene stays legible
const NORMAL_SCALE: f32 = 0.035;  // height units per world unit, for the normal
// DISPLACEMENT, in world units. The reference simulations displace real
// geometry, and that is why their ripples have height: a raised crest hides
// what is behind it and shifts what is under it. A flat plane with a bent
// normal can only ever change the shading, which is why these ripples read as a
// pattern painted on glass however the normal is tuned.
//
// The plane cannot be tessellated from here, so the RAY is solved against the
// displaced surface instead: guess the flat intersection, ask how tall the
// water is there, re-solve. Two iterations is plenty for a surface this shallow
// and it costs two extra grid samples.
const SIM_LIFT: f32 = 4.0;        // world units per unit of simulated height
const CHOP_LIFT: f32 = 0.5;
const SOLVE_STEPS: i32 = 2;
// The pool is a DISC. A square grid put a straight edge across the scene that
// nothing in the world explained; a circle reads as a pond.
//
// The fade is LONG — nearly half the radius — because a short one only moves
// the hard edge rather than removing it. And it damps the DISPLACEMENT as well
// as the opacity: a surface still standing in relief at the rim shows its
// boundary through the warp no matter how transparent it has become, which is
// the giveaway a short fade leaves behind.
const DISC_EDGE: f32 = 0.52;      // where the fade begins, as a fraction of the radius

// ── The resting surface, and the light on it ─────────────────────────────────
// The simulation is flat everywhere nothing has touched it, and flat water is a
// mirror. This is the chop that makes it a surface — and the reason the white
// specks in a reference photograph exist at all.
//
// ANISOTROPIC, which is the one thing the Blender graph was unambiguous about:
// every mapping node in it scales one axis and not the other. Stretching the
// domain is what turns noise into FLOW; isotropic noise reads as stone.
// Features every ~1.8 world units, which is where the surface stops reading as
// low resolution. AMP moves WITH it and inversely: a gradient noise's slope
// scales with its frequency, so making the chop 2.5x finer at a fixed amplitude
// makes it 2.5x steeper and floods the glints. Measured: (0.22, 0.55) and
// (0.55, 0.22) both land at 0.7% sparkle, and only the second has fine detail.
const CHOP_SCALE: f32 = 0.55;     // wave features per WORLD unit
const CHOP_ASPECT: f32 = 0.35;    // how far the domain is stretched crosswise
const CHOP_AMP: f32 = 0.22;
const CHOP_DRIFT: f32 = 0.35;
const CHOP_WARP: f32 = 0.55;      // how far the lattice is bent out of alignment
// The sun, named here because an effect cannot ask the scene for it. Points
// FROM the surface TOWARD the light.
const SUN_DIR: vec3f = vec3f(0.42, 0.66, -0.62);
const SUN_TINT: vec3f = vec3f(1.0, 1.0, 0.98);
// A very tight lobe, and it has to be. Measured on this chop: 400 lights 3% of
// the surface and reads as haze, 1800 lights 0.7% and reads as the scattered
// dashes a photograph has. The dots are LIGHT, not a texture — they sit where
// the wave normal happens to bisect sun and eye, which is why they line up
// along crests and why the ripples off her feet get them too.
const GLINT_POW: f32 = 1800.0;
const GLINT: f32 = 3.0;
// A lobe this tight is far NARROWER THAN A PIXEL, and that is fine only while
// the surface is calm. Once a dance fills the pool with ripples the normal
// swings within a single pixel, neighbouring pixels fall in and out of the
// lobe, and the highlight scintillates — the flashing dots. This is ordinary
// specular aliasing and the ordinary answer is Toksvig's: where the normal
// varies fast across a pixel, WIDEN the lobe to cover what it is varying
// between, and dim it to keep roughly the same energy. A calm surface is
// untouched; a churned one goes from glitter to sheen, which is what churned
// water does anyway.
//
// Measured WITHOUT fwidth, which cannot be called here: this function returns
// early for every ray that misses the disc or hits geometry first, so by the
// time a normal exists the control flow is not uniform and the derivative is
// illegal. The estimate below is the same quantity reasoned about instead —
// how much surface a pixel covers, times how steeply that surface is turning.
// Both of the things that actually cause the shimmer are in it: fine chop, and
// distance.
const GLINT_POW_MIN: f32 = 90.0;  // the widest the lobe is allowed to open
const GLINT_FILTER: f32 = 26.0;   // how strongly per-pixel normal wobble opens it
// Vertical arc of the frame, as a ratio — 2*tan(fov/2) for a 45 degree camera.
// Only sets the scale of the estimate above, alongside GLINT_FILTER.
const PIXEL_ARC: f32 = 0.83;

fn wHash2(p: vec2f) -> vec2f {
  let k = vec2f(0.3183099, 0.3678794);
  let x = p * k + k.yx;
  return -1.0 + 2.0 * fract(16.0 * k * fract(x.x * x.y * (x.x + x.y)));
}

/** Gradient noise with its ANALYTIC derivative: (value, d/dx, d/dy).
 *
 *  Analytic because the derivative IS the surface normal here, and a central
 *  difference is a blurred normal whose blur width is a constant nobody can
 *  defend. Gradient rather than value noise because value noise puts its
 *  extrema on the lattice and reads as blobs on a grid. */
fn wNoised(p: vec2f) -> vec3f {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  let du = 30.0 * f * f * (f * (f - 2.0) + 1.0);
  let ga = wHash2(i + vec2f(0.0, 0.0));
  let gb = wHash2(i + vec2f(1.0, 0.0));
  let gc = wHash2(i + vec2f(0.0, 1.0));
  let gd = wHash2(i + vec2f(1.0, 1.0));
  let va = dot(ga, f - vec2f(0.0, 0.0));
  let vb = dot(gb, f - vec2f(1.0, 0.0));
  let vc = dot(gc, f - vec2f(0.0, 1.0));
  let vd = dot(gd, f - vec2f(1.0, 1.0));
  let k1 = vb - va;
  let k2 = vc - va;
  let k3 = va - vb - vc + vd;
  let deriv = ga + u.x * (gb - ga) + u.y * (gc - ga) + u.x * u.y * (ga - gb - gc + gd)
            + du * vec2f(k1 + k3 * u.y, k2 + k3 * u.x);
  return vec3f(va + k1 * u.x + k2 * u.y + k3 * u.x * u.y, deriv);
}

/** Chop slope in WORLD units — three octaves, each rotated ~29 degrees off the
 *  last so the lattices never line up, each drifting at its own rate so the
 *  surface does not slide as one sheet. */
fn wChop(xz: vec2f, t: f32) -> vec3f {
  let r = mat2x2f(0.8776, 0.4794, -0.4794, 0.8776);
  // DOMAIN WARP, and it is not decoration. Gradient noise lives on a lattice,
  // and a specular lobe this tight picks out the lattice-regular extrema rather
  // than the waves — rendered out, the glints line up into a visible diagonal
  // grid of dots, which is the array that was flashing. Bending the coordinate
  // with a slower noise first destroys that alignment; it is the same trick the
  // Blender graph opens with, and it is there for the same reason.
  let w0 = wNoised(xz * CHOP_SCALE * 0.09 + vec2f(t * 0.05, 0.0)).x;
  let w1 = wNoised(xz * CHOP_SCALE * 0.09 + vec2f(11.3, 5.7)).x;
  let warped = xz + vec2f(w0, w1) * CHOP_WARP / max(CHOP_SCALE, 1e-4);
  var p = vec2f(warped.x * CHOP_SCALE * CHOP_ASPECT, warped.y * CHOP_SCALE);
  var g = vec2f(0.0);
  var hgt = 0.0;
  var amp = 1.0;
  for (var k = 0; k < 3; k = k + 1) {
    let nd = wNoised(p + vec2f(t * CHOP_DRIFT, t * CHOP_DRIFT * 0.6));
    hgt = hgt + nd.x * amp;
    g = g + nd.yz * amp;
    p = r * p * 2.03;
    amp = amp * 0.45;
  }
  return vec3f(g * CHOP_AMP, hgt);
}

fn wWorld(uv: vec2f) -> vec2f { return SIM_AT + (uv - vec2f(0.5)) * SIM_SPAN; }
fn wUV(xz: vec2f) -> vec2f { return (xz - SIM_AT) / SIM_SPAN + vec2f(0.5); }

fn gridStep(uv: vec2f, prev: vec4f, dt: f32) -> vec4f {
  // Flat and at rest. Unlike fog there IS a correct initial state for water and
  // it is nothing — every wave you see should be one that something made.
  if (rzGridFrame() == 0) { return vec4f(0.0); }

  // ONE FRAME PER STEP at most. This scheme's stability limit is a coefficient
  // near 2 per frame, so a 200ms hitch asking for twelve frames of acceleration
  // at once does not make slow water, it makes NaN that never leaves the grid
  // because the grid is its own input.
  let n = clamp(dt * 60.0, 0.0, 1.0);

  let te = rzGridTexel();
  let hL = rzGridPrev(uv - vec2f(te, 0.0)).x;
  let hR = rzGridPrev(uv + vec2f(te, 0.0)).x;
  let hD = rzGridPrev(uv - vec2f(0.0, te)).x;
  let hU = rzGridPrev(uv + vec2f(0.0, te)).x;

  var h = prev.x;
  var v = prev.y;

  let avg = (hL + hR + hD + hU) * 0.25;
  v += (avg - h) * WAVE_SPEED * n;
  v *= pow(DAMPING, n);
  h += v * n;
  h *= pow(HEIGHT_DAMPING, n);

  // ── Where she meets the water ──
  //
  // Every joint is measured against the WATERLINE, not against the floor, and
  // only the ones actually crossing it disturb anything. That is what makes
  // this the contact point rather than the foot: raise WATER_Y to her waist and
  // the ankles fall silent while the knees and hips take over, which is what
  // wading looks like. An arm swung down into the surface rings on its own.
  let world = wWorld(uv);
  for (var c = 0; c < rzSubjectCount(); c++) {
    for (var slot = 0; slot < LIMB_SLOTS; slot++) {
      let a = rzAnchor(c, slot);
      if (!a.valid) { continue; }
      let d = distance(world, a.pos.xz);
      if (d > STEP_R) { continue; }
      let imm = clamp(1.0 - abs(a.pos.y - WATER_Y) / STEP_BAND, 0.0, 1.0);
      if (imm <= 0.0) { continue; }
      // INTO THE HEIGHT, not the velocity, and briefly. Pressing velocity every
      // frame is a sustained impulse, and on an explicit scheme that excites the
      // GRID frequency: the ring came out a texel-scale bullseye carrying six
      // times the high-frequency energy this does. Wallace adds to height.
      let k = 0.5 - cos((1.0 - d / STEP_R) * 3.14159265) * 0.5;
      let speed = length(a.vel.xz) + abs(a.vel.y);
      h -= k * imm * (STEP_PUSH + speed * STEP_SPEED * 0.01) * n * dt * 6.0;
    }
    // The torso, for water deep enough to wade in. Wider and gentler than a
    // foot, because a body displaces more and slower.
    let hip = rzSubjectHip(c);
    let dh = distance(world, hip.xz);
    if (dh < STEP_R * 1.6) {
      let immH = clamp(1.0 - abs(hip.y - WATER_Y) / (STEP_BAND * 2.5), 0.0, 1.0);
      if (immH > 0.0) {
        let kh = 0.5 - cos((1.0 - dh / (STEP_R * 1.6)) * 3.14159265) * 0.5;
        h -= kh * immH * STEP_PUSH * 0.5 * n * dt * 6.0;
      }
    }
  }

  // Bounded, because the grid feeds itself: one bad frame is otherwise
  // permanent. Clamping the STATE is the insurance the ping-pong needs.
  h = clamp(h, -2.0, 2.0);
  v = clamp(v, -0.5, 0.5);
  return vec4f(h, v, 0.0, 0.0);
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let cam = rzCameraPos();
  let scenePos = bgWorldPos(ray, depth);
  let toScene = distance(scenePos, cam);

  // ── The camera is UNDER the surface ──
  //
  // Everything it sees is seen THROUGH water, so the whole frame is tinted by
  // the distance the ray covers before it leaves — either at the surface, if it
  // is looking up, or at whatever it hits.
  if (cam.y < WATER_Y) {
    let camR = length(wUV(cam.xz) - vec2f(0.5)) * 2.0;
    if (camR <= 1.0) {
      // Where the ray breaks the surface. Only ever ahead of us looking UP;
      // level or downward it never leaves, so the whole path is submerged.
      var exitT = 1e9;
      if (ray.y > 1e-4) { exitT = (WATER_Y - cam.y) / ray.y; }
      let path = max(min(toScene, exitT), 0.0);
      let absorbed = 1.0 - exp(-path / UNDER_RANGE);

      return vec4f(UNDER_TINT, clamp(absorbed, 0.0, 1.0) * UNDER_MAX);
    }
  }

  if (abs(ray.y) < 1e-4) { return vec4f(0.0); }
  let t = (WATER_Y - cam.y) / ray.y;
  if (t <= 0.0) { return vec4f(0.0); }

  // Solve the ray against the DISPLACED surface, not the flat plane. Each pass
  // asks how tall the water is where the last guess landed and re-intersects.
  var tt = t;
  var hit = cam + ray * tt;
  for (var i = 0; i < SOLVE_STEPS; i = i + 1) {
    let gg = wUV(hit.xz);
    // Flat by the rim, so the pool has no relief to show an edge with.
    let taper = 1.0 - smoothstep(DISC_EDGE, 1.0, length(gg - vec2f(0.5)) * 2.0);
    let lift = (rzGrid(gg).x * SIM_LIFT + wChop(hit.xz, time).z * CHOP_LIFT) * taper;
    tt = (WATER_Y + lift - cam.y) / ray.y;
    if (tt <= 0.0) { return vec4f(0.0); }
    hit = cam + ray * tt;
  }
  let g = wUV(hit.xz);
  // ROUND, not square. Radius from the middle, so the pool has no corners.
  let rad = length(g - vec2f(0.5)) * 2.0;
  if (rad > 1.0) { return vec4f(0.0); }

  // DEPTH, so this is a surface in the scene and not a decal over it. Whatever
  // the scene drew nearer than the plane stays in front; whatever it drew BEYOND
  // is underwater, which is how her legs go under with no per-model work.
  if (toScene < tt - 0.05) { return vec4f(0.0); }

  // ── The simulated surface, differenced into a slope ──
  let te = rzGridTexel();
  let sL = rzGrid(g - vec2f(te, 0.0)).x;
  let sR = rzGrid(g + vec2f(te, 0.0)).x;
  let sD = rzGrid(g - vec2f(0.0, te)).x;
  let sU = rzGrid(g + vec2f(0.0, te)).x;
  // TWO SOURCES, summed. The grid carries what something DID to the water and
  // is flat everywhere nothing has; the chop carries the surface being a
  // surface. Neither alone is water — the simulation alone is a mirror with
  // rings in it, and the chop alone cannot be disturbed.
  let simSlope = vec2f(sL - sR, sD - sU) / NORMAL_SCALE;
  let slope = simSlope + wChop(hit.xz, time).xy;
  let n = normalize(vec3f(slope.x, 1.0, slope.y));

  let view = normalize(cam - hit);
  let NV = clamp(dot(n, view), 0.0, 1.0);
  // Fresnel, floored: physical water reflects 2% from above, which on a stage
  // camera is no reflection at all.
  let fres = clamp(MIRRORING + (1.0 - MIRRORING) * pow(1.0 - NV, 5.0), 0.0, 1.0);

  // ── Depth: how much water the ray crossed before it hit anything ──
  // This is what a pool's colour actually IS, and it comes free — the scene's
  // own depth is already an argument to this function.
  let under = max(toScene - tt, 0.0);
  let column = clamp(under / COLUMN, 0.0, 1.0);
  let body = mix(SHALLOW, DEEP, column);

  // NO FOAM ON A RIPPLE. This was the whole error, and no threshold could fix
  // it because the layer should not exist: a ripple is a NORMAL, and it is seen
  // through the specular and the reflection that normal bends. Wallace's demo —
  // the reference this simulation comes from — renders its water with
  // reflection, refraction and caustics and has no foam anywhere in it. Painting
  // white on every crest gave a cloudy annulus around her feet that read as
  // spilt milk, and thinning it only made a thinner ring of the wrong thing.
  //
  // Foam is for where water MEETS something — a shoreline, a hull, her calves.
  // That is the collar, and it is the only white on this surface.
  let foam = 1.0 - smoothstep(0.0, WADE_FOAM, under);

  let bounce = reflect(-view, n);
  let sky = mix(SKY_LOW, SKY_HIGH, clamp(bounce.y, 0.0, 1.0));
  // The rim, faded and circular: the plane is unbounded and the simulation is
  // not, so without this the surface stops dead somewhere in the middle
  // distance, and a straight edge there reads as a bug where a curved one reads
  // as a bank. Squared, so it leaves gently rather than in a band — a linear
  // smoothstep over this distance still shows a ring where its slope peaks.
  //
  // Declared HERE rather than beside the alpha it also feeds: WGSL resolves
  // locals in source order inside a function, so a value used by the colour
  // below has to exist above it.
  let fade = 1.0 - smoothstep(DISC_EDGE, 1.0, rad);
  let rim = fade * fade;

  // THE GLINTS. Sun caught on a wave face — the white specks in the reference,
  // computed rather than painted, so they follow the chop AND the ripples she
  // makes without either being drawn twice.
  let half = normalize(normalize(SUN_DIR) + view);
  // How far the normal moves across ONE pixel, estimated. A pixel at distance
  // tt covers roughly tt * PIXEL_ARC / verticalResolution world units; multiply
  // by the slope to get how much the surface turns over that span. Far water
  // and choppy water both raise it, which is exactly when the lobe stops being
  // resolvable.
  let pixel = tt * PIXEL_ARC / max(rzResolution().y, 1.0);
  let wobble = clamp(length(slope) * pixel * GLINT_FILTER, 0.0, 1.0);
  let power = mix(GLINT_POW, GLINT_POW_MIN, wobble);
  let glint = pow(max(dot(n, half), 0.0), power) * GLINT * (1.0 - wobble * 0.55);

  // The detail fades WITH the surface. Left at full strength, the glints and
  // the collar go on sparkling after the water beneath them has gone, and a
  // ring of loose highlights is a worse edge than the one being hidden.
  let color = mix(body, max(sky, body), fres) * (1.0 - foam * rim)
            + FOAM * (foam * rim) + SUN_TINT * (glint * rim);

  // COVERAGE BY WATER COLUMN, not a constant. Absorption is what makes a body
  // in water read as submerged: near the surface almost nothing is taken out,
  // and a metre down the colour is gone. A single opacity cannot say both, and
  // at 0.9 it said neither — it drew a flat sheet over her legs and she looked
  // like she was standing BEHIND the water. Fresnel still takes it to opaque
  // edge-on, which is what hides the far bank.
  let depthAlpha = mix(CLEAR, OPACITY, column);
  let alpha = clamp(mix(depthAlpha, 1.0, pow(1.0 - NV, 5.0)) + foam * 0.5, 0.0, 1.0) * rim;
  return vec4f(color, alpha);
}

// CRT Static — an old set, flickering.
//
// A scanned beam, a phosphor grille, static, a rolling bar, tape sway and the
// unsteady brightness of a set that has been on too long.
//
// BOTH HALVES: an overlay laid over everything, and a GLITCH that displaces the
// picture itself where there is picture to displace.
//
// The second half used to shift the ground's colour away from the background
// beside it, and that was not a tuning problem. rzScene is linear and
// pre-tone-map, so a resample has to put what it fetched back into display
// space, and doing that by hand — a Reinhard shoulder, a 2.2 gamma — is near
// enough at a glance and wrong everywhere it matters. rzSceneDisplay runs the
// composite's OWN chain instead: exposure, view transform, grade, gamma. Fetch a
// pixel at its own uv and you get the pixel that is already there, so a
// displacement of zero is invisible and the treated region stops reading a shade
// off from the untreated one.
//
// A FILTER OVER THE WHOLE FRAME. The picture is rebuilt from two sources — the
// scene where it was drawn, rzBackground's colour where it was not — and the
// tube is applied to all of it. Treating only the drawn part is what made the
// ground read differently from the sky beside it: a real set has no opinion
// about which of its pixels are geometry.
//
// WHAT IT ERASES: background EFFECTS. Stars, a waveform, anything on the
// background mount composes in the pass after this one, so it cannot be read and
// cannot be re-drawn. Over a TRANSPARENT background — a backdrop video, an alpha
// export — there is nothing to rebuild, so those pixels take the overlay alone
// and keep what they had.
//
// Alpha-over rather than additive: half of what makes a CRT read as a CRT is the
// black between its lines, and additive can only brighten.
//
// THE GRILLE IS AN HONEST COMPROMISE. A real shadow mask multiplies the image
// PER CHANNEL — red survives the red stripe, green does not. Compositing gives
// one scalar coverage, so per-channel attenuation is not expressible. What it
// does instead is darken at the gaps by the mask's own profile and lay the
// phosphor colour back over the stripes, which lands close on ordinary content
// and drifts on heavily saturated colour.
//
// TWO CLOCKS, both quantised. A preview at 60fps and an export at 30 would
// otherwise draw different noise from the same second of the same scene.
//
// MEASURED IN THE PICTURE, never in device pixels — a 320-line tube is 320 lines
// whether shown in a 700px preview or written to 4K. Each pattern also fades
// where the output cannot resolve it: a grille finer than the sampling that
// draws it is not a grille, it is moire that crawls.

// ── The beam ──
// COARSER THAN A REAL TUBE. 480 lines is what a set had, and at that pitch the
// scan is nearly invisible on a modern display — the pattern has to be seen to
// do any work, so this is a tube you are sitting closer to than you were.
const SCAN_LINES: f32 = 320.0;    // lines down the whole picture
const SCAN_DEPTH: f32 = 0.26;     // how black the gaps between them go, 0..1
// GAUSSIAN, not a sine. A sine spends as much of the line dark as lit and reads
// as a grey wash; a real line is a beam with a bright core and a fast falloff.
const SCAN_WIDTH: f32 = 0.24;     // its width as a fraction of the line pitch

// ── The phosphor grille ──
const TRIADS: f32 = 160.0;        // RGB triads across the whole picture
const GRILLE_DEPTH: f32 = 0.14;   // darkening in the gaps between stripes
const GRILLE_TINT: f32 = 0.05;    // phosphor colour laid back over the stripes

// ── Static ──
const GRAIN: f32 = 0.07;         // strength at its peak
const GRAIN_FLOOR: f32 = 0.30;    // fraction of GRAIN always present, 0..1
const GRAIN_COLS: f32 = 420.0;    // grain cells across the picture
const GRAIN_ROWS: f32 = 236.0;    // and down it
const GRAIN_HZ: f32 = 20.0;       // times a second the static is redrawn
const BURST_HZ: f32 = 0.7;        // how fast the signal wanders in and out

// ── The roll ──
const ROLL_SPEED: f32 = 0.26;     // pictures a second the bar travels
const ROLL_WIDTH: f32 = 0.10;     // its height, as a fraction of the picture
const ROLL_LIFT: f32 = 0.05;      // how much its body brightens
const ROLL_EDGE: f32 = 0.10;      // how much its leading edge darkens

// ── The tape ──
// The mask sways and tears while the picture under it holds still. A viewer
// reads an unstable signal from an unstable mask, which is the part of tape
// damage an overlay can carry honestly.
const SWAY: f32 = 0.0045;         // slow horizontal drift, fraction of the width
const SWAY_HZ: f32 = 1.6;         // how fast it wanders
const JITTER: f32 = 0.35;         // share of the sway that is per-line hash, 0..1
const TEAR_HZ: f32 = 1.1;         // times a second a tear is rolled for
const TEAR_ODDS: f32 = 0.42;      // how often that roll lands, 0..1
const TEAR_WIDTH: f32 = 0.030;    // height of a torn band, fraction of the picture
const TEAR_DRAG: f32 = 0.055;     // how far it drags the mask sideways
const TEAR_LIFT: f32 = 0.14;      // how much it flares

// ── The glitch ──
// AS EVENTS, NOT ON A PERIOD. One envelope on a fixed loop is the most
// predictable thing a shader can do: watch it twice and you know when the next
// one lands, how hard it hits and how long it stays. It stops reading as a fault
// and starts reading as an animation.
//
// So time is cut into slots and each slot ROLLS for a burst — most come up
// empty, which is where the quiet stretches come from. A slot that fires picks
// its own start inside itself, its own length, its own strength, its own BAND of
// the picture, and its own mix of tearing against dropout. Nothing is shared
// between two bursts except the machinery, so they arrive off the beat, at
// different sizes, in different places, and no two are the same kind of wrong.
//
// Deterministic in the second, not in the frame: every roll is a hash of the
// slot index, so an export replays exactly what the preview showed.
const SLOT: f32 = 0.9;            // seconds per roll
const ODDS: f32 = 0.26;           // chance a slot fires at all, 0..1
const LIFE_MIN: f32 = 0.06;       // shortest burst, seconds
const LIFE_MAX: f32 = 0.55;       // longest. Past ~0.6s a burst stops reading as an event
const BAND_MIN: f32 = 0.16;       // tightest band a burst takes, fraction of height
const BAND_MAX: f32 = 1.5;        // widest — past 1 it takes the whole frame
// HOW HARD, and it is three separate rolls rather than one. A burst has a peak,
// a SHAPE that peak is reached through, and a flutter riding on top of it. Vary
// only the peak and every burst is still the same gesture at a different volume,
// which is what a single multiplier gets you.
const PEAK_MIN: f32 = 0.22;       // a burst you could miss
const PEAK_MAX: f32 = 1.0;        // one you could not
const SHAPE_MIN: f32 = 0.22;      // low holds near its peak — a sustained dropout
const SHAPE_MAX: f32 = 2.2;       // high spikes and is gone — a single torn frame
const STUTTER: f32 = 0.55;        // how far the strength drops between flutters
const STUTTER_HZ: f32 = 22.0;     // flutters a second, in real time
// DROPOUT STREAKS. A displacement can only be seen where there is detail to
// displace — tear a flat sky sideways and nothing appears to happen — so tearing
// and block-fetching alone put every visible glitch on the one part of the frame
// that has texture. These replace a band of the picture outright, so they read
// wherever they land, and that is what spreads the fault over the whole height.
const STREAK_LINES: f32 = 110.0;  // bands the picture can drop out in
const STREAK_ODDS: f32 = 0.34;    // share of them gone at the peak of a burst
const STREAK_MIX: f32 = 0.7;      // how completely a dropped band is replaced
const STREAK_HZ: f32 = 26.0;      // times a second they are re-rolled
const WRAP: f32 = 240.0;          // seconds before the fault pattern repeats
const IDLE: f32 = 0.01;           // how much survives between bursts
// WHAT A QUIET STRETCH LOOKS LIKE. Not zero — a set is never perfectly received
// — but low enough that the picture reads as simply being on a tube, with the
// faults gone until the next one arrives.
const REST: f32 = 0.06;           // share of the tube's unrest present at rest
const WARP: f32 = 0.030;          // barrel bulge. The centre stays undistorted
const SLIP: f32 = 0.045;          // how far a torn band goes, fraction of the width
const TEAR_BANDS: f32 = 16.0;     // bands the height is cut into. Fewer is chunkier
const TEAR_SHARE: f32 = 0.30;     // share of them torn at a burst's peak, 0..1
const TEAR_RATE: f32 = 14.0;      // times a second the selection is redrawn
const TEAR_RAGGED: f32 = 0.30;    // per-line roughness on a torn band
// NOTHING TEARS UNTIL A BURST IS REALLY UNDER WAY. A linear response meant the
// resting trickle was always displacing something somewhere, which is what made
// the whole scene look like it was flowing.
const GATE_LO: f32 = 0.18;        // glitch level where tearing starts at all
const GATE_HI: f32 = 0.55;        // and where it is fully in
const SLIP_HZ: f32 = 30.0;        // times a second the tearing is redrawn
const ABERR: f32 = 1.7;           // colour separation, pixels of a 1440-line frame
const BLOCK_BIAS: f32 = 0.03;     // share of the frame dropping out at rest
const BLOCK_GAIN: f32 = 0.22;     // and how much more at the peak
const BLOCK_SHIFT: f32 = 0.055;    // how far a dropped block is fetched from
const BLOCK_HZ: f32 = 30.0;       // times a second the blocks are redrawn

// ── The tube ──
const FLICKER: f32 = 0.030;       // swing of the overall brightness
const FLICKER_HZ: f32 = 11.0;     // times a second it is re-judged
const FLASH: f32 = 0.10;          // strength of the occasional flash
const FLASH_HZ: f32 = 0.55;       // times a second a flash is re-judged
const INTERLACE: f32 = 0.5;       // 0 off, 1 full half-line field offset
const FIELD_HZ: f32 = 50.0;       // fields a second, PAL. 60 for NTSC
const VIGNETTE: f32 = 0.32;       // darkening toward the corners
const DIM: f32 = 0.03;           // a flat veil over everything, 0 for none
const PHOSPHOR: vec3f = vec3f(0.62, 0.80, 1.00);  // colour of the bright parts

/**
 * A stable hash, 0..1. NO sin, and that is the whole point.
 *
 * The usual shader hash multiplies a dot product through sine. Its inputs here
 * are tick counters — floor(clock * 30), and one of them scaled by another 300
 * — which after a few minutes of playback reach the millions, and sine of an
 * argument that large has no precision left in f32: argument reduction throws
 * the meaningful bits away and the numbers stop changing. Which looks like a set
 * that glitched normally for a while and then locked into one displacement, at
 * one strength, in one place, forever.
 *
 * BACKGROUNDING THE TAB IS THE FAST PATH TO IT. Animation stops while hidden and
 * the clock does not, so coming back moves the counters by minutes in one step
 * — straight past the cliff rather than drifting toward it.
 *
 * The multiply-and-fract construction below has no such cliff. It degrades
 * slowly and evenly instead of falling off a shelf, and it costs less.
 */
fn crtHash(p3: vec3f) -> f32 {
  var p = fract(p3 * vec3f(0.1031, 0.1030, 0.0973));
  p = p + vec3f(dot(p, p.yzx + vec3f(33.33)));
  return fract((p.x + p.y) * p.z);
}

/**
 * One roll of a burst's dice, 0..1. Decorrelated in BOTH arguments.
 *
 * The sin-based hash beside this is fine for a pixel — thrown at a whole frame
 * of coordinates its flaws average out — but a burst asks it a handful of
 * questions a second, all with the same slot index and only the seed changing.
 * That is exactly where fract(sin(dot(...))) is worst: the answers correlate,
 * and a value meant to scatter over the frame instead lands in a narrow part of
 * its range. It put every glitch across her legs.
 *
 * This is Dave Hoskins' construction: fold both arguments into three channels on
 * irrational-ish strides, mix them against each other, and take the fraction.
 * Cheap, and it decorrelates the seeds rather than merely disguising them.
 */
fn crtRand(n: f32, seed: f32) -> f32 {
  var p = fract(vec3f(n * 0.1031 + seed * 0.0711, n * 0.1030 + seed * 0.1367, n * 0.0973 + seed * 0.0331));
  p = p + vec3f(dot(p, p.yzx + vec3f(33.33)));
  return fract((p.x + p.y) * p.z);
}

/** Value noise, 0..1. Smooth in every axis, so a displacement built from it
 *  slides rather than steps. */
fn crtNoise(p: vec3f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = mix(crtHash(i + vec3f(0.0, 0.0, 0.0)), crtHash(i + vec3f(1.0, 0.0, 0.0)), u.x);
  let b = mix(crtHash(i + vec3f(0.0, 1.0, 0.0)), crtHash(i + vec3f(1.0, 1.0, 0.0)), u.x);
  let c = mix(crtHash(i + vec3f(0.0, 0.0, 1.0)), crtHash(i + vec3f(1.0, 0.0, 1.0)), u.x);
  let e = mix(crtHash(i + vec3f(0.0, 1.0, 1.0)), crtHash(i + vec3f(1.0, 1.0, 1.0)), u.x);
  return mix(mix(a, b, u.y), mix(c, e, u.y), u.z);
}

/** A value that wanders rather than steps: two ticks of a hash, crossfaded. A
 *  hard cut every tick is a fault; this is a set that is merely old. */
fn crtDrift(t: f32, seed: f32) -> f32 {
  let i = floor(t);
  return mix(crtHash(vec3f(i, seed, 13.0)), crtHash(vec3f(i + 1.0, seed, 13.0)), smoothstep(0.0, 1.0, fract(t)));
}

/** src OVER dst, both premultiplied, so repeated OVER composes associatively.
 *  The caller divides the colour back out once at the end. */
fn crtOver(dst: vec4f, col: vec3f, alpha: f32) -> vec4f {
  let a = clamp(alpha, 0.0, 1.0);
  return vec4f(col * a + dst.rgb * (1.0 - a), a + dst.a * (1.0 - a));
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let res = rzResolution();
  let aspect = res.x / max(res.y, 1.0);
  // THE CLOCK, WRAPPED. Every tick counter below derives from this, and one that
  // counts up forever eventually swamps any hash's precision however good it is.
  // Wrapping means the fault pattern repeats every WRAP seconds — imperceptible
  // in noise, longer than any export, and it survives the tab being hidden for
  // an hour and handing the effect a clock that jumped.
  let t = time - floor(time / WRAP) * WRAP;

  // ── The glitch, as whichever burst is loudest right now ──
  // Three slots are examined, not one: a burst starts anywhere inside its own
  // slot and can outlive it, so the previous and next both have to be asked or
  // events would be clipped at the seams — which would put a rhythm back in.
  var amt = 0.0;
  var bandC = 0.5;
  var bandH = 9.0;
  var tearMix = 1.0;
  var blockMix = 1.0;
  let slotNow = floor(t / max(SLOT, 1e-3));
  for (var k = -1; k <= 1; k = k + 1) {
    let s = slotNow + f32(k);
    // Most slots roll nothing. This is the whole source of the quiet.
    if (crtRand(s, 1.0) > ODDS) { continue; }
    let start = s * SLOT + crtRand(s, 2.0) * SLOT;
    let life = mix(LIFE_MIN, LIFE_MAX, crtRand(s, 3.0));
    let u = (t - start) / max(life, 1e-3);
    if (u < 0.0 || u > 1.0) { continue; }
    // THE SHAPE IS ROLLED TOO. A raised sine with a per-burst exponent: below one
    // it holds near its peak and reads as a sustained dropout, above one it
    // spikes and is gone before you locate it. The exponent is what stops every
    // burst being the same gesture at a different volume.
    let shape = mix(SHAPE_MIN, SHAPE_MAX, crtRand(s, 9.0));
    let peak = mix(PEAK_MIN, PEAK_MAX, crtRand(s, 4.0));
    // AND IT FLUTTERS ON THE WAY. A smooth arc is still a curve someone drew;
    // real signal loss judders while it happens. Rolled against real seconds
    // rather than against the burst's own progress, so a long burst and a short
    // one shake at the same rate instead of the short one appearing calmer.
    let stut = mix(1.0 - STUTTER, 1.0, crtRand(s * 137.0 + floor(t * STUTTER_HZ), 12.0));
    let env = pow(sin(u * 3.1415927), shape) * peak * stut;
    // The loudest burst wins rather than the sum: two overlapping events should
    // not stack into something neither of them was.
    if (env <= amt) { continue; }
    amt = env;
    // Over the WHOLE height, and a little past both ends so a burst can sit half
    // off the top or the bottom rather than always being fully on screen.
    bandC = crtRand(s, 5.0) * 1.3 - 0.15;
    bandH = mix(BAND_MIN, BAND_MAX, crtRand(s, 6.0));
    // What KIND of wrong this one is. A burst that is all tear and no dropout
    // looks nothing like one that is all dropout, and having both vary is most
    // of why no two read the same.
    tearMix = mix(0.1, 1.0, crtRand(s, 7.0));
    blockMix = mix(0.1, 1.0, crtRand(s, 8.0));
  }
  // WHERE it lands. Outside the band a burst still registers faintly, so a tear
  // across the middle does not leave the rest of the frame conspicuously clean.
  let inBand = 1.0 - smoothstep(0.0, max(bandH, 1e-3), abs(uv.y - bandC));
  // OUTSIDE THE BAND still counts for half. At a quarter a burst was effectively
  // confined to its band, so one stripe of the frame moved while the rest sat
  // perfectly still — which reads as a mask, not as a signal fault.
  let glitch = clamp(IDLE + amt * mix(0.3, 1.0, inBand), 0.0, 1.0);

  var acc = vec4f(0.0);

  // ── The glass ──
  let d = (uv - vec2f(0.5)) * vec2f(aspect, 1.0);
  let vig = clamp(dot(d, d) * VIGNETTE, 0.0, 1.0);
  acc = crtOver(acc, vec3f(0.0), clamp(DIM + vig, 0.0, 1.0));

  // ── Tape instability ──
  // Two timescales, because one alone does not read as tape. The sway wanders
  // over seconds and moves the whole mask together; the jitter is a fresh hash
  // per LINE per field, which is what makes an edge look torn rather than merely
  // displaced. A tear is a band where both jump at once.
  let field = crtHash(vec3f(floor(t * FIELD_HZ), 3.0, 5.0));
  let offset = select(0.0, 0.5 * INTERLACE, field > 0.5);
  let sway = (crtDrift(t * SWAY_HZ, 41.0) - 0.5) * 2.0;
  let lineId = floor(uv.y * SCAN_LINES);
  let jitter = (crtHash(vec3f(lineId, floor(t * FIELD_HZ), 17.0)) - 0.5) * 2.0;
  let tearTick = floor(t * TEAR_HZ);
  // Rolled, not scheduled: most ticks pass without one, so tears arrive in an
  // uneven rhythm instead of on a beat.
  let rolled = step(1.0 - TEAR_ODDS, crtHash(vec3f(tearTick, 51.0, 2.0)));
  let tearY = crtHash(vec3f(tearTick, 52.0, 3.0));
  let tear = rolled * (1.0 - smoothstep(0.0, TEAR_WIDTH, abs(uv.y - tearY)));
  // SCALED BY THE BURST. Sway and tears running constantly is a set that is
  // always broken, and a viewer stops reading them as faults within seconds.
  // Between bursts this collapses to almost nothing and the picture sits still.
  let unrest = mix(REST, 1.0, glitch);
  let shift = (mix(sway, jitter, JITTER) * SWAY + tear * TEAR_DRAG * sign(sway)) * unrest;
  // Everything patterned across the picture reads this rather than uv.x, so the
  // grille and the grain move together — a grain that stayed put while the
  // grille swayed would read as two overlays.
  let mx = uv.x + shift;

  // ── The scanned beam ──
  let linePx = res.y / SCAN_LINES;
  let scanOk = smoothstep(1.4, 2.6, linePx);
  let along = fract(uv.y * SCAN_LINES + offset) - 0.5;
  let beam = exp(-(along * along) / max(2.0 * SCAN_WIDTH * SCAN_WIDTH, 1e-5));
  acc = crtOver(acc, vec3f(0.0), SCAN_DEPTH * (1.0 - beam) * scanOk);

  // ── The phosphor grille ──
  // Three stripes to a triad, each a soft lobe rather than a hard band: a hard
  // one aliases into stripes of the wrong colour the moment the picture is not
  // an exact multiple of the mask.
  let subPx = res.x / (TRIADS * 3.0);
  let grilleOk = smoothstep(1.2, 2.4, subPx);
  let sub = fract(mx * TRIADS) * 3.0;
  let ph = vec3f(
    exp(-pow((sub - 0.5) * 1.7, 2.0)),
    exp(-pow((sub - 1.5) * 1.7, 2.0)),
    exp(-pow((sub - 2.5) * 1.7, 2.0)),
  );
  let lit = max(ph.r, max(ph.g, ph.b));
  acc = crtOver(acc, vec3f(0.0), GRILLE_DEPTH * (1.0 - lit) * grilleOk);
  acc = crtOver(acc, normalize(ph + vec3f(0.001)), GRILLE_TINT * lit * grilleOk);

  // ── The roll ──
  // Its body lifts and its LEADING edge drops dark, which is what reads as a
  // roll rather than a moving stripe.
  let roll = fract(uv.y + t * ROLL_SPEED);
  let body = 1.0 - smoothstep(0.0, ROLL_WIDTH, roll);
  let lead = 1.0 - smoothstep(0.0, ROLL_WIDTH * 0.22, fract(roll + ROLL_WIDTH * 0.22));
  acc = crtOver(acc, vec3f(0.0), ROLL_EDGE * lead * unrest);
  acc = crtOver(acc, PHOSPHOR, ROLL_LIFT * body * unrest);

  // ── Static ──
  // IN WAVES, not at a constant level. Held flat it reads as film grain, which
  // is a property of the stock and always there; a tube's noise is a property of
  // the SIGNAL, so it breathes.
  let burst = mix(GRAIN_FLOOR, 1.0, crtDrift(t * BURST_HZ, 29.0)) * mix(REST, 1.0, glitch);
  let cell = floor(vec2f(mx, uv.y) * vec2f(GRAIN_COLS, GRAIN_ROWS));
  let n = crtHash(vec3f(cell, floor(t * GRAIN_HZ)));
  // Signed, so static darkens as often as it lightens. A one-sided grain reads
  // as dust on the lens; a tube's noise sits either side of the picture.
  let swing = (n - 0.5) * 2.0;
  acc = crtOver(acc, select(vec3f(0.0), PHOSPHOR, swing > 0.0), GRAIN * burst * abs(swing));

  // The torn band flares as it drags — the tape losing contact, not just
  // slipping. Drawn after the grain so it sits on top of it.
  acc = crtOver(acc, PHOSPHOR, tear * TEAR_LIFT * unrest);

  // ── The tube's own brightness ──
  acc = crtOver(acc, vec3f(0.0), FLICKER * crtDrift(t * FLICKER_HZ, 7.0));
  // AND ITS OCCASIONAL FLASH. Raised to a high power so most of the curve sits
  // near nothing and only its peaks arrive: a flash that happens continuously is
  // a brightness setting, and what makes a recording read as old is that it is
  // mostly steady and then briefly is not.
  acc = crtOver(acc, PHOSPHOR, FLASH * pow(crtDrift(t * FLASH_HZ, 61.0), 6.0) * glitch);

  let over = vec4f(acc.rgb, clamp(acc.a, 0.0, 1.0));


  // Polar barrel: the radius pushed out by its own square, so the centre is
  // untouched and only the edges bow. On the SAMPLE coordinate, never the pixel.
  let q = uv * 2.0 - vec2f(1.0);
  let rad = length(q);
  let ang = atan2(q.y, q.x);
  let bent = rad / (1.0 - WARP * rad * rad);
  let lens = vec2f(bent * cos(ang), bent * sin(ang)) * 0.5 + vec2f(0.5);

  // Two noises MULTIPLIED: one alone displaces every line a little, the product
  // is mostly zero with occasional strong lines, which is what tearing looks
  // like. Quantised in t so an export matches its preview.
  let sq = floor(t * SLIP_HZ);
  let ln = lens.y * SCAN_LINES;
  // WHICH BANDS ARE TORN, and mostly none of them.
  //
  // A continuous noise over the height does not tear, it FLOWS: every band is
  // displaced by a little, all the time, and the picture reads as a liquid
  // rather than a broken signal. Tearing is discrete — a few bands jump, the
  // rest hold perfectly still, and the contrast between them is the whole
  // effect.
  //
  // So the height is cut into bands and each one is PICKED or not. Most are not,
  // even at a burst's peak. A picked band takes a whole displacement rather than
  // a fraction of one, and holds it for a tick instead of being redrawn every
  // frame — a band that changes every frame is a shimmer, not a tear.
  let gate = smoothstep(GATE_LO, GATE_HI, glitch);
  let bandId = floor(lens.y * TEAR_BANDS);
  let tick = floor(t * TEAR_RATE);
  let picked = step(1.0 - TEAR_SHARE * gate, crtRand(bandId * 13.0 + tick, 41.0));
  let howFar = (crtRand(bandId * 17.0 + tick, 43.0) - 0.5) * 2.0;
  // A ragged per-line edge ON THE TORN BANDS ONLY, so a tear does not look like
  // a rectangle someone slid sideways.
  let ragged = (crtNoise(vec3f(0.0, ln * 0.9, tick)) * 2.0 - 1.0) * TEAR_RAGGED;
  let drag = picked * (howFar + ragged) * SLIP * tearMix * gate + shift;

  // Blocky dropout: bands in x and y crossed, each block fetched from elsewhere.
  // NOT multiplied up. The reference scales this tick by 300 to decorrelate it,
  // which is exactly the move that pushes a hash past its precision; the hash
  // separates its own axes now, so the tick goes in as it is.
  let bt = floor(t * BLOCK_HZ);
  let level = BLOCK_BIAS + BLOCK_GAIN * blockMix * glitch;
  let bx = step(crtNoise(vec3f(0.0, lens.x * 3.0, bt)), level);
  let by = step(crtNoise(vec3f(0.0, lens.y * 4.0, bt)), level);
  let block = clamp(bx * by, 0.0, 1.0);
  let jump = (crtHash(vec3f(floor(ln), bt, 7.0)) - 0.5) * 2.0 * BLOCK_SHIFT;

  let st = vec2f(lens.x + drag + jump * block, lens.y);

  // ── The picture ──
  // COVERAGE, not a depth test. The scene's alpha is what carries the ground's
  // radial fade and its opacity; a depth test is binary and the plane writes
  // depth across its whole square whatever its alpha does, which is what turned
  // a sheet fading into the distance into a hard-edged slab.
  let cover = clamp(rzSceneAlpha(st), 0.0, 1.0);
  let bg = rzBackground();
  let solid = bg.w > 0.5;
  // One fetch per gun, through the composite's own transform, so an undisplaced
  // pixel comes back exactly as it already was.
  let sep = vec2f(ABERR / 1440.0 * (1.0 + glitch), 0.0);
  let guns = vec3f(
    rzSceneDisplay(st + sep).r,
    rzSceneDisplay(st).g,
    rzSceneDisplay(st - sep).b,
  );
  // Premultiplied throughout. Over a solid background the frame is opaque and
  // the background stands in behind the scene; over a TRANSPARENT one there is
  // nothing to stand in — a backdrop video lives behind the canvas — so the
  // coverage passes through and whatever is back there shows exactly as far as
  // the scene lets it.
  let picRgb = select(guns * cover, guns * cover + bg.rgb * (1.0 - cover), solid);
  let picA = select(cover, 1.0, solid);

  // The overlay, over the displaced picture, both premultiplied.
  let outRgb = over.rgb + picRgb * (1.0 - over.a);
  let outA = over.a + picA * (1.0 - over.a);
  var col = clamp(outRgb / max(outA, 1e-6), vec3f(0.0), vec3f(1.0));

  // ── Dropout streaks ──
  // The half of the fault that does not need detail underneath it. Rolled per
  // band per tick, so they scatter over the full height rather than following
  // whatever happens to be textured.
  let sId = floor(uv.y * STREAK_LINES);
  let gone = step(1.0 - STREAK_ODDS * glitch, crtRand(sId * 3.0 + floor(t * STREAK_HZ), 31.0));
  let lum = dot(col, vec3f(0.2126, 0.7152, 0.0722));
  col = mix(col, PHOSPHOR * clamp(lum * 1.5 + 0.10, 0.0, 1.0), gone * STREAK_MIX * glitch);
  return vec4f(col, clamp(outA, 0.0, 1.0));
}

// 8-Bit — the whole frame re-rendered as pixel art.
//
// A FILTER, not a mask: the picture is rebuilt from the scene where it was drawn
// and rzBackground's colour where it was not, and all of it goes through one
// grid. A monitor has no opinion about which of its pixels are geometry.
//
// THREE THINGS THAT MADE AN EARLIER VERSION LOOK WRONG, all of them choices.
//
// 1. IT DITHERED FLAT COLOUR. A solid background sits between two palette steps,
//    so an ordered matrix alternates on it forever and the result is a permanent
//    chequerboard where art would have one flat block. Dither exists to break up
//    BANDING, so it belongs where the picture is changing and nowhere else. It
//    is now gated on how much the picture actually varies here.
//
// 2. IT AVERAGED AWAY THIN FEATURES. A box filter preserves a feature's
//    PRESENCE and destroys its CONTRAST: a one-pixel white grid line inside an
//    eight-pixel cell contributes an ninth of the colour and comes out grey.
//    Pixel art is made of exactly such lines. So the cell keeps its mean AND its
//    most extreme sample, and leans toward the extreme — which is what a person
//    drawing this by hand does, picking the colour that says what the cell IS
//    rather than the colour of its average.
//
// 3. IT RESTYLED THE COLOURS. A contrast curve, a hue shift and a saturation
//    lift stacked on top of each other, and white came out warm and grey. They
//    are all still here and all default to nearly nothing, because matching the
//    scene is the first job and styling is the optional one.
//
// THE RESOLUTION IS A REAL ONE. 240 rows is the NES and the SNES; the Game Boy is
// 144, the Mega Drive 224, a modern indie canvas 270.

// ── The screen ──
// COUNTED DOWN THE HEIGHT, not across the width, and that is what keeps a pixel
// the same size when the export aspect changes.
//
// The camera's field of view is anchored VERTICALLY: narrow the frame to 9:16
// and the horizontal view narrows with it, so the subject grows relative to the
// width. Counting cells across the width then hands her more of them and the
// pixels come out finer — the same scene at a different pixel size, which is
// exactly what changing the aspect should not do. Counted down the height, the
// one axis the lens holds fixed, she keeps her pixel size and a wider frame
// simply gets more pixels beside her.
const ROWS: f32 = 270.0;          // pixels DOWN the picture. 144 Game Boy, 224 Mega Drive, 240 NES, 270 modern
// TAPS PER PIXEL, CHOSEN FROM THE CELL'S ACTUAL SIZE — not a constant, because a
// constant is what made an export look different from its preview. A cell is
// about 2.5 screen pixels in the editor and about 8 at 4K; a fixed 3x3 covers the
// first completely and under a sixth of the second, so the same rule produced a
// different average and the export was a different picture.
//
// Matched to the cell instead, both average the whole cell and agree. Capped
// because the cost is the square of it, and past the cap the extra taps are
// refining an average that has already converged.
const SAMPLE_CAP: i32 = 6;        // most taps per axis, so at most 36 per pixel
const SAMPLE_MIN: i32 = 2;        // fewest, so a tiny cell is still averaged
// How far each pixel leans from the cell's average toward the colour that OWNS
// it. 0 is a plain box filter and blurs thin lines into their surroundings; 1
// commits to the owner outright, which is what a person drawing the cell does.
const PUNCH: f32 = 0.80;

// ── The palette ──
const LEVELS: f32 = 8.0;          // shades per channel. 4 is severe, 12 is gentle
const DITHER: f32 = 0.9;          // strength where the picture varies. 0 for none
const DITHER_LO: f32 = 0.02;      // variation below which nothing is dithered
const DITHER_HI: f32 = 0.10;      // and above which it is dithered fully

// ── Legibility ──
// SHARPEN, and it is the answer to small dark features disappearing. An eye is
// two or three cells of dark inside a lot of light skin, so the owner test gives
// those cells to the skin — right by area, wrong for reading a face. Biasing the
// test toward dark would fix the eyes and dim every bright thin line in the same
// stroke, which is the trade the grid lines already lost once.
//
// An unsharp step has no such asymmetry: it pushes each pixel further from its
// NEIGHBOURS, so a dark feature goes darker and a bright line goes brighter, and
// nothing has to be preferred over anything. It reuses the four neighbour reads
// the outline already takes, so it costs nothing.
const SHARPEN: f32 = 0.55;        // 0 leaves the picture alone, 1 is aggressive
// HOW READILY A DARK ACCENT CLAIMS ITS PIXEL. Eyes, nostrils, the line of a
// mouth: a few cells of near-black inside a lot of skin, so by area the skin
// owns them and they wash out. An artist draws those pixels dark deliberately,
// and pixel art without them reads as a blurred face.
//
// Tilting the whole owner test toward dark would fix the eyes and dim every
// bright thin line in the same stroke — the grid lines have lost that trade
// once already. But the two are told apart easily: an eye's dark end sits FAR
// below its cell's mean, while a grid line's dark end is just the ordinary floor
// of the picture. So the tilt is scaled by how deep the dark end actually is,
// and a bright line barely feels it.
const DARK_BIAS: f32 = 0.26;      // 0 is pure area, higher lets dark accents survive

// ── Styling, all optional ──
const CONTRAST: f32 = 1.04;       // S-curve before snapping. 1 leaves values alone
const SAT: f32 = 1.05;            // colour lift. 1 leaves it alone
const HUE_SHIFT: f32 = 0.0;       // shadows cool and lights warm. 0 is faithful
const COOL: vec3f = vec3f(0.86, 0.92, 1.12);
const WARM: vec3f = vec3f(1.10, 1.03, 0.90);

// ── The outline ──
// SILHOUETTES ONLY, by default, and the interior edge is off for a reason.
//
// An interior outline darkens wherever VALUE steps hard between neighbouring
// cells — which a white grid line on a magenta floor does about as hard as
// anything can. So the lines came out ringed in black when they should be pure
// white, and because the test is a threshold, cells flipped it on and off as the
// camera turned: that was the flashing too, not the colour choice.
//
// A form's edge is where COVERAGE falls away, and that is a different question
// with a stable answer. Raise OUTLINE_INNER if you want interior lines and can
// live with them landing on anything bright and thin.
const OUTLINE: f32 = 0.80;        // how strongly a silhouette is inked. 0 for none
const OUTLINE_INNER: f32 = 0.0;   // and an edge INSIDE a form. See above
const EDGE_LUMA: f32 = 0.20;      // value difference across a cell that counts as an edge
const EDGE_COVER: f32 = 0.26;     // coverage drop outward that counts as a silhouette
// THE INK, and it is a colour rather than a percentage. Darkening a cell by a
// fraction does almost nothing to black shorts and turns pale skin grey, so the
// same rim reads as a line in one place and as smudge in another. Pixel art inks
// a form in a DEFINITE dark, tinted toward the form so it still belongs to it —
// which is what INK_TINT balances: 0 is a flat near-black, 1 is purely a darker
// version of whatever the cell already was.
const INK: vec3f = vec3f(0.05, 0.04, 0.08);
const INK_TINT: f32 = 0.45;

/** The classic 4x4 ordered (Bayer) matrix, centred on zero. A var rather than a
 *  const because WGSL only allows a dynamic index into a function-scope array. */
fn ebBayer(p: vec2f) -> f32 {
  var m = array<f32, 16>(
    0.0, 8.0, 2.0, 10.0,
    12.0, 4.0, 14.0, 6.0,
    3.0, 11.0, 1.0, 9.0,
    15.0, 7.0, 13.0, 5.0,
  );
  let x = i32(p.x) & 3;
  let y = i32(p.y) & 3;
  return m[y * 4 + x] / 16.0 - 0.46875;
}

fn ebLuma(c: vec3f) -> f32 { return dot(c, vec3f(0.2126, 0.7152, 0.0722)); }

/** One cell, point-sampled: display colour and coverage. For the neighbour reads
 *  the outline needs — the cell being drawn gets the filter below instead. */
fn ebPeek(at: vec2f) -> vec4f {
  return vec4f(rzSceneDisplay(at), clamp(rzSceneAlpha(at), 0.0, 1.0));
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let res = rzResolution();
  let aspect = res.x / max(res.y, 1.0);
  // SQUARE PIXELS: the row count is fixed and the columns follow from the frame's
  // shape, so a pixel is square at any aspect and the same size at 4K as in the
  // preview.
  let grid = vec2f(max(ROWS * aspect, 1.0), ROWS);
  let ij = floor(uv * grid);

  // ── The pixel: its average, and its most distinctive sample ──
  var sum = vec3f(0.0);
  var cov = 0.0;
  var hiC = vec3f(0.0);
  var loC = vec3f(1.0);
  var hiL = -1.0;
  var loL = 2.0;
  // One tap per screen pixel the cell spans, so the filter reads the same
  // fraction of the cell whatever it is being drawn into.
  let cellPx = res.y / max(grid.y, 1.0);
  let n = clamp(i32(ceil(cellPx)), SAMPLE_MIN, SAMPLE_CAP);
  for (var i = 0; i < n; i = i + 1) {
    for (var j = 0; j < n; j = j + 1) {
      let o = (vec2f(f32(i), f32(j)) + vec2f(0.5)) / f32(n) - vec2f(0.5);
      let s = ebPeek((ij + vec2f(0.5) + o) / grid);
      sum = sum + s.rgb * s.a;
      cov = cov + s.a;
      let l = ebLuma(s.rgb) * s.a;
      if (l > hiL) { hiL = l; hiC = s.rgb; }
      if (l < loL) { loL = l; loC = s.rgb; }
    }
  }
  let inv = 1.0 / f32(n * n);
  let cover = cov * inv;
  let mean = sum * inv / max(cover, 1e-6);
  let meanL = ebLuma(mean);
  // WHICH COLOUR OWNS THIS PIXEL, not which is most extreme.
  //
  // Taking the extreme was wrong and the grid lines showed it: any cell merely
  // GRAZED by a bright line went fully bright, so a one-pixel line bloomed to
  // fill a cell, and because the line runs diagonally in perspective the cells
  // it grazes alternate — which is the dashed, blobby mess.
  //
  // Where the mean sits between the two extremes says how much of the cell each
  // one covers: a mean near the dark end means the bright sample is a sliver.
  // So the pixel takes whichever actually owns it, crossed over smoothly so a
  // cell hovering at the boundary does not flicker between them frame to frame.
  let frac = clamp((meanL - loL) / max(hiL - loL, 1e-5), 0.0, 1.0);
  // How far below the cell's own mean its dark end reaches, as a share of that
  // mean. Near 1 for an eye on skin; small for a white line on a mid ground,
  // whose dark end is simply the ground.
  let depth2 = clamp((meanL - loL) / max(meanL, 1e-3), 0.0, 1.0);
  let bias = DARK_BIAS * depth2;
  // A WIDE crossover, and that width is the difference between a line that sits
  // still and one that flashes. A cell holding a thin line lands near the middle
  // of this range, and the camera moving a hair walks it back and forth across
  // the boundary — with a narrow crossover that is a hard flip every frame. Wide,
  // it drifts through the mean instead, which is stable because the mean is what
  // an average is.
  // Shifting the crossover UP means more of the cell has to be bright before the
  // bright colour takes it — which is the same thing as letting a deep dark
  // minority win.
  let owns = mix(loC, hiC, smoothstep(0.22 + bias, 0.78 + bias, frac));
  var col = mix(mean, owns, PUNCH);
  // How much this cell is CHANGING. Nothing below is applied where it is flat.
  let spread = hiL - loL;

  // ── The outline ──
  // Two kinds, because pixel art uses both: a SILHOUETTE where coverage falls
  // away to a neighbouring cell, and an INTERIOR edge where value steps hard
  // inside a form. Sampled on the cell grid, so the line lands on pixel
  // boundaries rather than cutting across them.
  let e = vec2f(1.0, 0.0) / grid;
  let f = vec2f(0.0, 1.0) / grid;
  let c0 = (ij + vec2f(0.5)) / grid;
  let nR = ebPeek(c0 + e);
  let nL = ebPeek(c0 - e);
  let nU = ebPeek(c0 + f);
  let nD = ebPeek(c0 - f);
  let dLuma = max(max(abs(meanL - ebLuma(nR.rgb)), abs(meanL - ebLuma(nL.rgb))),
                  max(abs(meanL - ebLuma(nU.rgb)), abs(meanL - ebLuma(nD.rgb))));
  // HOW FAR COVERAGE FALLS GOING OUTWARD, not how much it differs. The absolute
  // difference fires on both sides of an edge and on any antialiased wobble
  // along it, which is what made the rim patchy; the drop to the emptiest
  // neighbour fires once, on the inside, where the ink belongs.
  let minN = min(min(nR.a, nL.a), min(nU.a, nD.a));
  let dCover = clamp(cover - minN, 0.0, 1.0);
  let inner = smoothstep(EDGE_LUMA, EDGE_LUMA * 2.2, dLuma) * OUTLINE_INNER;
  // Only where this cell is genuinely part of the form. Without it the rim also
  // lands on the near-empty cells just outside her, and a form outlined on both
  // sides is twice as thick as it should be.
  let rim = smoothstep(EDGE_COVER, EDGE_COVER * 2.0, dCover) * OUTLINE * smoothstep(0.35, 0.7, cover);
  let darken = clamp(max(inner, rim), 0.0, 1.0);

  // ── Legibility ──
  // Against the four neighbouring CELLS, not the pixels inside this one: the
  // comparison has to be at the resolution the art is drawn at, or it sharpens
  // detail the grid is about to throw away.
  let around = (nR.rgb + nL.rgb + nU.rgb + nD.rgb) * 0.25;
  col = clamp(col + (col - around) * SHARPEN, vec3f(0.0), vec3f(1.0));

  // ── Styling, gently ──
  col = clamp((col - vec3f(0.5)) * CONTRAST + vec3f(0.5), vec3f(0.0), vec3f(1.0));
  let tint = mix(COOL, WARM, smoothstep(0.12, 0.88, ebLuma(col)));
  col = clamp(col * mix(vec3f(1.0), tint, HUE_SHIFT), vec3f(0.0), vec3f(1.0));
  let grey = ebLuma(col);
  col = clamp(vec3f(grey) + (col - vec3f(grey)) * SAT, vec3f(0.0), vec3f(1.0));
  // Before the snap, so the ink lands ON a palette step rather than as a colour
  // the palette does not contain.
  let ink = mix(INK, col * 0.28, INK_TINT);
  col = mix(col, ink, darken);

  // ── Over the background, then snapped ──
  let bg = rzBackground();
  let solid = bg.w > 0.5;
  col = select(col, col * cover + bg.rgb * (1.0 - cover), solid);
  let outA = select(cover, 1.0, solid);

  // DITHERED ONLY WHERE IT VARIES. On a flat fill the matrix would chequer
  // forever; banding is what it is for, and a flat fill has none.
  let vary = max(spread, dLuma);
  let amount = DITHER * smoothstep(DITHER_LO, DITHER_HI, vary);
  let q = max(LEVELS, 2.0);
  col = col + vec3f(ebBayer(ij) * amount / q);
  return vec4f(clamp(floor(col * q + vec3f(0.5)) / q, vec3f(0.0), vec3f(1.0)), outA);
}
